function rampartSimulate(createStrategy, seed, maxTicks, rec) {
  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return (t ^ (t >>> 14)) >>> 0; }; }
  const TT = {
    bolt:   { i: 0, cost: 50,  dmg: 26,  per: 8,  range: 300, splash: 0,  slow: 0,  pierce: 0, g: 1, a: 1 },
    cannon: { i: 1, cost: 90,  dmg: 60,  per: 24, range: 260, splash: 90, slow: 0,  pierce: 0, g: 1, a: 0 },
    frost:  { i: 2, cost: 70,  dmg: 10,  per: 12, range: 240, splash: 0,  slow: 30, pierce: 0, g: 1, a: 1 },
    lance:  { i: 3, cost: 120, dmg: 180, per: 36, range: 360, splash: 0,  slow: 0,  pierce: 1, g: 1, a: 0 },
    flak:   { i: 4, cost: 80,  dmg: 40,  per: 10, range: 320, splash: 70, slow: 0,  pierce: 0, g: 0, a: 1 }
  };
  const ET = {
    grunt:     { hp: 60,  speed: 10, bounty: 4, leak: 1, air: 0, first: 1, weight: 10 },
    runner:    { hp: 40,  speed: 20, bounty: 4, leak: 1, air: 0, first: 2, weight: 4 },
    wisp:      { hp: 50,  speed: 12, bounty: 6, leak: 2, air: 1, first: 3, weight: 3 },
    brute:     { hp: 150, speed: 6,  bounty: 9, leak: 3, air: 0, first: 4, weight: 3 },
    splitter:  { hp: 90,  speed: 8,  bounty: 6, leak: 2, air: 0, first: 6, weight: 2 },
    mender:    { hp: 70,  speed: 8,  bounty: 7, leak: 2, air: 0, first: 8, weight: 1 },
    splitling: { hp: 0,   speed: 12, bounty: 1, leak: 1, air: 0, first: 0, weight: 0 }
  };
  const ORDER = ['grunt', 'runner', 'wisp', 'brute', 'splitter', 'mender'];
  const GP = [[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]];
  const AP = [[0,6],[21,6],[21,11],[23,11]];
  const GLEN = 4600, ALEN = 2600;
  const SLOTS = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]];
  function setPos(e) {
    const P = e.air ? AP : GP; let d = e.progress;
    for (let i = 0; i < P.length - 1; i++) {
      const ax = P[i][0], ay = P[i][1], bx = P[i + 1][0], by = P[i + 1][1];
      const L = (Math.abs(bx - ax) + Math.abs(by - ay)) * 100;
      if (d <= L || i === P.length - 2) {
        if (d > L) d = L;
        e.x = ax * 100 + 50 + (bx > ax ? d : bx < ax ? -d : 0);
        e.y = ay * 100 + 50 + (by > ay ? d : by < ay ? -d : 0);
        return;
      }
      d -= L;
    }
  }
  function view(e) {
    return { id: e.id, type: e.type, hp: e.hp, maxHp: e.maxHp, x: e.x, y: e.y, air: e.air, armor: e.armor,
      speed: e.speed, slowed: e.slow > 0 ? 1 : 0, remaining: e.len - e.progress };
  }
  const strat = createStrategy();
  const rng = mulberry32(seed);
  const log = [];
  let gold = 250, baseHp = 10, nextId = 1, wave = 0, fallTick = -1;
  const turrets = []; for (let i = 0; i < 16; i++) turrets.push(null);
  let enemies = [];
  let queue = [], qHead = 0;
  const waves = {};
  let mult = 1000, multWave = 1;
  function mOf(w) { while (multWave < w) { mult = Math.floor(mult * 108 / 100); multWave++; } return mult; }
  function genWave(w) {
    const types = []; let sum = 0;
    for (const t of ORDER) if (ET[t].first <= w) { types.push(t); sum += ET[t].weight; }
    const n = 4 + Math.floor(3 * w / 5), out = [];
    for (let i = 0; i < n; i++) {
      let r = rng() % sum;
      for (const t of types) { if (r < ET[t].weight) { out.push(t); break; } r -= ET[t].weight; }
    }
    waves[w] = out;
  }
  function mkEnemy(type, w, maxHp, progress) {
    const T = ET[type];
    const e = { id: nextId++, type: type, wave: w, hp: maxHp, maxHp: maxHp, progress: progress, air: T.air,
      len: T.air ? ALEN : GLEN, speed: T.speed, bounty: T.bounty, leak: T.leak, age: 0, slow: 0, x: 0, y: 0,
      armor: type === 'grunt' ? Math.floor(w / 4) : type === 'brute' ? 6 + w : 0 };
    setPos(e); return e;
  }
  genWave(1);
  let fell = false;
  for (let tick = 0; tick < maxTicks && !fell; tick++) {
    // 1. wave start
    if (tick >= 20 && (tick - 20) % 40 === 0) {
      wave = (tick - 20) / 40 + 1;
      gold += Math.min(50, Math.floor(gold * 5 / 100)) + 10 + 2 * wave;
      genWave(wave + 1);
      const state = { tick: tick, wave: wave, gold: gold, baseHp: baseHp, slots: [], enemies: enemies.map(view),
        nextWave: waves[wave + 1].slice() };
      for (let i = 0; i < 16; i++) {
        const t = turrets[i];
        state.slots.push({ slot: i, x: SLOTS[i][0] * 100 + 50, y: SLOTS[i][1] * 100 + 50,
          turret: t ? { type: t.type, tier: t.tier, spent: t.spent } : null });
      }
      let acts = strat.plan(state);
      if (!Array.isArray(acts)) acts = [];
      const na = Math.min(32, acts.length);
      for (let k = 0; k < na; k++) {
        const a = acts[k]; if (!a || typeof a !== 'object') continue;
        const s = a.slot;
        if (!Number.isInteger(s) || s < 0 || s > 15) continue;
        if (a.op === 'build') {
          const T = TT.hasOwnProperty(a.type) ? TT[a.type] : null;
          if (!T || turrets[s] || gold < T.cost) continue;
          gold -= T.cost;
          turrets[s] = { slot: s, type: a.type, T: T, tier: 1, spent: T.cost, cd: 0, dmg: T.dmg, range: T.range,
            x: SLOTS[s][0] * 100 + 50, y: SLOTS[s][1] * 100 + 50 };
          log.push([tick, 'B', s, T.i]);
          if (rec) rec.ev(tick, 'B', s, T.i);
        } else if (a.op === 'upgrade') {
          const t = turrets[s]; if (!t || t.tier >= 3) continue;
          const c = t.tier === 1 ? t.T.cost : 2 * t.T.cost;
          if (gold < c) continue;
          gold -= c; t.spent += c; t.tier++; t.dmg = Math.floor(t.dmg * 16 / 10); t.range += 30;
          log.push([tick, 'U', s, t.tier]);
          if (rec) rec.ev(tick, 'U', s, t.tier);
        } else if (a.op === 'sell') {
          const t = turrets[s]; if (!t) continue;
          gold += Math.floor(t.spent * 70 / 100); turrets[s] = null;
          log.push([tick, 'S', s, 0]);
          if (rec) rec.ev(tick, 'S', s, t.T.i);
        }
      }
      const comp = waves[wave];
      for (let i = 0; i < comp.length; i++) queue.push({ tick: tick + 4 * i, wave: wave, idx: i, type: comp[i] });
      const rest = queue.slice(qHead); qHead = 0;
      rest.sort(function (p, q) { return p.tick - q.tick || p.wave - q.wave || p.idx - q.idx; });
      queue = rest;
      delete waves[wave];
    }
    // 2. spawn
    while (qHead < queue.length && queue[qHead].tick <= tick) {
      const q = queue[qHead++];
      enemies.push(mkEnemy(q.type, q.wave, Math.floor(ET[q.type].hp * mOf(q.wave) / 1000), 0));
    }
    // 3. move
    {
      const keep = [];
      for (let i = 0; i < enemies.length; i++) {
        const e = enemies[i];
        e.progress += e.slow > 0 ? Math.floor(e.speed * 60 / 100) : e.speed;
        if (e.progress >= e.len) {
          baseHp -= e.leak;
          log.push([tick, 'L', e.id, baseHp]);
          if (rec) rec.ev(tick, 'L', e.id, baseHp, e);
          if (baseHp <= 0) {
            log.push([tick, 'F', wave, 0]); fallTick = tick; fell = true;
            for (let j = i + 1; j < enemies.length; j++) keep.push(enemies[j]);
            break;
          }
        } else { setPos(e); keep.push(e); }
      }
      enemies = keep;
      if (fell) { if (rec) rec.tick(tick, enemies, turrets, gold, baseHp, wave, waves[wave + 1], true); break; }
    }
    // 4. age & heal
    for (let i = 0; i < enemies.length; i++) {
      const e = enemies[i]; e.age++;
      if (e.type === 'mender' && e.age % 20 === 0) {
        for (let j = 0; j < enemies.length; j++) {
          const o = enemies[j], dx = o.x - e.x, dy = o.y - e.y;
          if (dx * dx + dy * dy <= 22500) { o.hp = Math.min(o.maxHp, o.hp + Math.floor(o.maxHp * 8 / 100)); }
        }
        if (rec) rec.ev(tick, 'H', e.id, 0, e);
      }
    }
    // 5. turrets
    for (let s = 0; s < 16; s++) {
      const t = turrets[s]; if (!t) continue;
      if (t.cd > 0) { t.cd--; if (t.cd > 0) continue; }
      const T = t.T, r2 = t.range * t.range, cands = [];
      for (let i = 0; i < enemies.length; i++) {
        const e = enemies[i];
        if (e.air ? !T.a : !T.g) continue;
        const dx = e.x - t.x, dy = e.y - t.y;
        if (dx * dx + dy * dy <= r2) cands.push(e);
      }
      if (!cands.length) continue;
      let tgt = null;
      if (typeof strat.target === 'function') {
        const id = strat.target({ slot: s, type: t.type, tier: t.tier, x: t.x, y: t.y, range: t.range }, cands.map(view));
        for (let i = 0; i < cands.length; i++) if (cands[i].id === id) { tgt = cands[i]; break; }
      }
      if (!tgt) {
        tgt = cands[0];
        for (let i = 1; i < cands.length; i++) if (cands[i].len - cands[i].progress < tgt.len - tgt.progress) tgt = cands[i];
      }
      const hits = [];
      if (T.splash > 0) {
        const s2 = T.splash * T.splash;
        for (let i = 0; i < enemies.length; i++) {
          const e = enemies[i];
          if (e.air ? !T.a : !T.g) continue;
          const dx = e.x - tgt.x, dy = e.y - tgt.y;
          if (dx * dx + dy * dy <= s2) hits.push(e);
        }
      } else hits.push(tgt);
      for (let i = 0; i < hits.length; i++) {
        const e = hits[i];
        e.hp -= T.pierce ? t.dmg : Math.max(1, t.dmg - e.armor);
        if (T.slow > 0) e.slow = T.slow;
      }
      t.cd = T.per;
      if (rec) rec.ev(tick, 'X', s, T.i, tgt);
      let anyDead = false;
      for (let i = 0; i < hits.length; i++) if (hits[i].hp <= 0) { anyDead = true; break; }
      if (anyDead) {
        const keep = [], born = [];
        for (let i = 0; i < enemies.length; i++) {
          const e = enemies[i];
          if (e.hp > 0) { keep.push(e); continue; }
          gold += e.bounty;
          log.push([tick, 'K', e.id, s]);
          if (rec) rec.ev(tick, 'K', e.id, s, e);
          if (e.type === 'splitter') {
            const mh = Math.max(1, Math.floor(e.maxHp / 4));
            for (let k = 0; k < 3; k++) born.push(mkEnemy('splitling', e.wave, mh, e.progress));
          }
        }
        enemies = keep.concat(born);
      }
    }
    // 6. slow timers
    for (let i = 0; i < enemies.length; i++) if (enemies[i].slow > 0) enemies[i].slow--;
    if (rec) rec.tick(tick, enemies, turrets, gold, baseHp, wave, waves[wave + 1], false);
  }
  const endTick = fallTick >= 0 ? fallTick : maxTicks;
  const str = JSON.stringify(log);
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 0x01000193); }
  return { score: Math.round((endTick - 20) * 100 / 40) / 100, fallTick: fallTick, log: log,
    hash: (h >>> 0).toString(16).padStart(8, '0') };
}
if (typeof module !== 'undefined') module.exports = rampartSimulate;
