function createStrategy() {
  var CFG = /*CFG*/(typeof __CFG !== 'undefined' ? __CFG : null)/*END*/;
  var TYPES = ['bolt', 'cannon', 'frost', 'lance', 'flak'];
  var COST = [50, 90, 70, 120, 80];
  var DMG = { bolt: [26, 41, 65], cannon: [60, 96, 153], frost: [10, 16, 25], lance: [180, 288, 460], flak: [40, 64, 102] };
  var SPL = { bolt: 0, cannon: 90, frost: 0, lance: 0, flak: 70 };
  var TI = { bolt: 0, cannon: 1, frost: 2, lance: 3, flak: 4 };
  var W = CFG.w;
  function plan(state) {
    var gold = state.gold, acts = [], tiers = [], types = [], need = [], i;
    for (i = 0; i < 16; i++) {
      var t = state.slots[i] && state.slots[i].turret;
      tiers.push(t ? t.tier : 0); types.push(t ? t.type : null); need.push(0);
    }
    var steps = CFG.steps, skipped = 0;
    for (i = 0; i < steps.length && acts.length < 32; i++) {
      var s = steps[i][0], ty = steps[i][1];
      need[s]++;
      if (tiers[s] >= need[s]) continue;
      if (tiers[s] > 0 && types[s] !== TYPES[ty]) continue;
      var cost = tiers[s] === 2 ? 2 * COST[ty] : COST[ty];
      if (gold < cost) { skipped++; if (skipped > CFG.look) break; need[s] = 99; continue; }
      gold -= cost;
      if (tiers[s] === 0) { acts.push({ op: 'build', slot: s, type: TYPES[ty] }); types[s] = TYPES[ty]; }
      else acts.push({ op: 'upgrade', slot: s });
      tiers[s]++;
    }
    return acts;
  }
  function target(t, c) {
    var n = c.length;
    if (n === 1) return c[0].id;
    var type = t.type, w = W[TI[type]], dmg = DMG[type][t.tier - 1], sp = SPL[type], sp2 = sp * sp;
    var best = -1e18, bid = c[0].id, i, j;
    var pierce = type === 'lance';
    for (i = 0; i < n; i++) {
      var e = c[i], sc = 0;
      var ed = pierce ? dmg : dmg - e.armor; if (ed < 1) ed = 1;
      var kill = e.hp <= ed ? 1 : 0;
      if (ed > e.hp) ed = e.hp;
      if (sp) {
        var tot = 0, kills = 0;
        for (j = 0; j < n; j++) {
          var o = c[j], dx = o.x - e.x, dy = o.y - e.y;
          if (dx * dx + dy * dy <= sp2) {
            var d2 = dmg - o.armor; if (d2 < 1) d2 = 1;
            if (o.hp <= d2) { d2 = o.hp; kills++; }
            tot += d2;
          }
        }
        sc = w[0] * tot / dmg + w[4] * kills;
      } else {
        sc = w[0] * ed / dmg + w[4] * kill;
      }
      sc += w[1] * (1 - e.remaining / 4600);
      if (e.air) sc += w[2];
      if (e.type === 'mender') sc += w[3];
      if (!e.slowed) sc += w[5];
      if (e.type === 'brute') sc += w[6];
      sc += w[7] * e.hp / e.maxHp;
      if (sc > best) { best = sc; bid = e.id; }
    }
    return bid;
  }
  return { plan: plan, target: target };
}

