(function () {
  'use strict';
  const DURATION = 100;
  const TPS = 20, NT = 2020;

  // ------------------------------------------------------------------ seeded visual randomness
  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
  const vrand = mulberry32(42);
  const RT = new Float32Array(4096);
  for (let i = 0; i < 4096; i++) RT[i] = vrand();
  function rv(i, j) { return RT[(Math.imul(i | 0, 73) + Math.imul(j | 0, 151) + 7) & 4095]; }
  function snoise(t, ch) {
    const i = Math.floor(t), f = t - i, u = f * f * (3 - 2 * f);
    const a = RT[(i + ch * 977) & 4095], b = RT[(i + 1 + ch * 977) & 4095];
    return (a + (b - a) * u) * 2 - 1;
  }

  // ------------------------------------------------------------------ replay recording
  const TYPE_IDX = { grunt: 0, brute: 1, runner: 2, wisp: 3, splitter: 4, splitling: 5, mender: 6 };
  const PREV_ORDER = ['grunt', 'runner', 'wisp', 'brute', 'splitter', 'mender'];
  const SLOTS = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]];
  const frames = [];
  const EV = { shots: [], kills: [], heals: [], leaks: [], builds: [], waves: [] };
  const aimCur = new Float32Array(16), sinceCur = new Int32Array(16).fill(-10000);
  let lastWave = 0;
  const rec = {
    ev: function (tick, code, a, b, e) {
      if (code === 'X') {
        EV.shots.push({ t: tick, slot: a, ty: b, x: e.x / 100, z: e.y / 100, air: e.air });
        aimCur[a] = Math.atan2(e.x / 100 - (SLOTS[a][0] + 0.5), e.y / 100 - (SLOTS[a][1] + 0.5));
      } else if (code === 'K') {
        EV.kills.push({ t: tick, x: e.x / 100, z: e.y / 100, ty: TYPE_IDX[e.type], air: e.air });
      } else if (code === 'H') {
        EV.heals.push({ t: tick, x: e.x / 100, z: e.y / 100 });
      } else if (code === 'L') {
        EV.leaks.push({ t: tick, hp: b, dmg: e.leak });
      } else {
        EV.builds.push({ t: tick, code: code, slot: a, b: b });
        if (code === 'B') { sinceCur[a] = tick; aimCur[a] = 0; }
      }
    },
    tick: function (tick, enemies, turrets, gold, baseHp, wave, next) {
      const n = enemies.length;
      const fr = { n: n, id: new Int32Array(n), ty: new Uint8Array(n), pr: new Float32Array(n), hp: new Float32Array(n),
        sl: new Uint8Array(n), v: new Float32Array(n), age: new Uint8Array(n), tur: new Uint8Array(32),
        aim: new Float32Array(aimCur), since: new Int32Array(sinceCur), gold: gold, hp10: Math.max(0, baseHp), wave: wave,
        next: new Uint8Array(6) };
      for (let i = 0; i < n; i++) {
        const e = enemies[i];
        fr.id[i] = e.id; fr.ty[i] = TYPE_IDX[e.type]; fr.pr[i] = e.progress; fr.hp[i] = Math.max(0, e.hp / e.maxHp);
        fr.sl[i] = e.slow > 0 ? 1 : 0; fr.v[i] = e.slow > 0 ? Math.floor(e.speed * 60 / 100) : e.speed;
        fr.age[i] = Math.min(255, e.age);
      }
      for (let s = 0; s < 16; s++) { const t = turrets[s]; if (t) { fr.tur[s * 2] = t.T.i + 1; fr.tur[s * 2 + 1] = t.tier; } }
      if (next) for (let i = 0; i < next.length; i++) fr.next[PREV_ORDER.indexOf(next[i])]++;
      if (wave !== lastWave) { EV.waves.push({ t: tick, w: wave }); lastWave = wave; }
      frames[tick] = fr;
    }
  };
  const result = rampartSimulate(createStrategy, 42, NT, rec);
  for (let i = 0; i < NT; i++) if (!frames[i]) frames[i] = frames[i - 1];
  const fallTick = result.fallTick;
  const fallTime = fallTick >= 0 ? fallTick / TPS : Infinity;

  // routes in world units
  function mkRoute(pts) {
    const P = pts.map(function (p) { return [p[0] + 0.5, p[1] + 0.5]; }), cum = [0];
    for (let i = 1; i < P.length; i++) cum.push(cum[i - 1] + Math.abs(P[i][0] - P[i - 1][0]) + Math.abs(P[i][1] - P[i - 1][1]));
    return { P: P, cum: cum, len: cum[cum.length - 1] };
  }
  const GR = mkRoute([[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]]);
  const AR = mkRoute([[0,6],[21,6],[21,11],[23,11]]);
  const rp = [0, 0];
  function routePos(R, d) {
    if (d < 0) d = 0; if (d > R.len) d = R.len;
    let i = 1; while (i < R.cum.length - 1 && d > R.cum[i]) i++;
    const a = R.P[i - 1], b = R.P[i], L = R.cum[i] - R.cum[i - 1], u = L > 0 ? (d - R.cum[i - 1]) / L : 0;
    rp[0] = a[0] + (b[0] - a[0]) * u; rp[1] = a[1] + (b[1] - a[1]) * u;
    return rp;
  }

  // trauma timeline (closed form between events)
  const traumaEv = [];
  (function () {
    let pv = 0, pt = 0;
    const list = EV.leaks.map(function (l) { return { t: l.t / TPS, add: 0.3 }; });
    if (fallTick >= 0) list.push({ t: fallTime, add: 1.0 });
    for (const e of list) { const v = Math.min(1, Math.max(0, pv - (e.t - pt)) + e.add); traumaEv.push({ t: e.t, v: v }); pv = v; pt = e.t; }
  })();
  function traumaAt(t) {
    let v = 0;
    for (let i = traumaEv.length - 1; i >= 0; i--) if (traumaEv[i].t <= t) { v = Math.max(0, traumaEv[i].v - (t - traumaEv[i].t)); break; }
