        const e = enemies[i];
        fr.id[i] = e.id; fr.ty[i] = TYPE_IDX[e.type]; fr.pr[i] = e.progress; fr.hp[i] = Math.max(0, e.hp / e.maxHp);
        fr.sl[i] = e.slow > 0 ? 1 : 0; fr.v[i] = e.slow > 0 ? Math.floor(e.speed * 60 / 100) : e.speed;
