input.content:
import re, os, subprocess, sys
D = os.path.dirname(os.path.abspath(__file__))
h = open(sys.argv[1]).read()
st = re.search(r'<script id="rampart-strategy">(.*?)</script>', h, re.S).group(1)
sm = re.search(r'<script id="rampart-sim">(.*?)</script>', h, re.S).group(1)
for bad in ['window', 'document', 'THREE', 'Math.random', 'Date', 'performance']:
    assert bad not in st, bad
for bad in ['window', 'document', 'THREE', 'Audio']:
    assert bad not in sm, bad
print('scripts in html:', len(re.findall(r'<script', h)), 'external refs:', re.findall(r'(?:src|href)="([^"]+)"', h))
test = st + '\nconst myStrategy = createStrategy;\n' + sm + r'''
const A = () => ({ plan(s) { const a = []; let g = s.gold; for (const sl of s.slots) if (!sl.turret && g >= 50) { a.push({ op: "build", slot: sl.slot, type: "bolt" }); g -= 50; } return a; } });
let r = rampartSimulate(A, 42, 12020); print('A', r.score, r.fallTick, r.log.length, r.hash, r.hash === '82a5353d' && r.fallTick === 1035 && r.log.length === 166 ? 'MATCH' : 'MISMATCH');
const B = () => ({ plan(s) { return s.wave===1?[{op:"build",slot:3,type:"cannon"},{op:"build",slot:6,type:"frost"}]:s.wave===3?[{op:"upgrade",slot:3},{op:"build",slot:12,type:"flak"}]:s.wave===6?[{op:"build",slot:8,type:"lance"},{op:"sell",slot:6}]:[]; } });
r = rampartSimulate(B, 7, 12020); print('B', r.score, r.fallTick, r.log.length, r.hash, r.hash === '2e8858d7' && r.fallTick === 457 && r.log.length === 48 ? 'MATCH' : 'MISMATCH');
r = rampartSimulate(myStrategy, 42, 2020); print('seed42 replay', r.score, r.fallTick, r.hash);
r = rampartSimulate(myStrategy, 42, 12020); print('seed42 full', r.score, r.fallTick, r.hash);
let t = Date.now(), tot = 0; for (let i = 0; i < 100; i++) tot += rampartSimulate(myStrategy, 900001 + i * 7919, 12020).score; print('fresh100', (tot / 100).toFixed(3), (Date.now() - t) / 100 + ' ms/game');
'''
open(os.path.join(D, 'e2e.js'), 'w').write(test)
print(subprocess.run(['/System/Library/Frameworks/JavaScriptCore.framework/Versions/Current/Helpers/jsc', os.path.join(D, 'e2e.js')], capture_output=True, text=True).stdout)

